--[[
游戏启动过程调用ejoysdk的更新检查接口

current_res_info_arr：数组，游戏关心的资源以及当前的信息，每一项为一个obj，信息如下。键值参考：{@link M.RES_INFO_KEY}
    namespace: string 必传，命名空间
    res_key: string 必传，资源标识
    version: string 可选，当前使用中的资源版本名称，如果不传则会使用轻舟本地缓存的应用成功的资源版本，例如：1.2.3
    pkg_project_name 可选，string 资源的包体属性，从包体的资源信息中获取。用于覆盖安装场景检查本地缓存目录的资源是否兼容，如果不兼容，则清除本地的资源目录
    pkg_res_version 可选，string, 包体资源版本，例如：1.2.3
    res_save_base_path 可选，string, 当前资源的目标存储路径，例如游戏的外部patch资源目录
    res_save_storage_type 可选，string, 结合res_save_base_path一起使用，可以得到目标完整路径。可选值见：{@link M.STORAGE_TYPE}
opts: table, 可选参数, {@link #M.NAMESPACE_UPDATE_OPTIONS}
    @param {@link M.NAMESPACE_UPDATE_OPTIONS.FORCE_CHECK_UPDATE} bool, 默认为false, 如果设置为true，则强制重新检查更新
listeners：资源相关的一些监听器
1. on_startup_update_complete：启动过程更新完成回调，该回调返回两个参数
    @param succ 是否成功，true: 成功， false：失败
    @param ... 可变参数. 如果succ为true，则该可变参数为空；如果succ 为false，则可变参数为code, msg

2. on_receive_res_update_confirm 启动过程和游戏中监听到资源更新信息变更确认回调，游戏需要在回调中确认是否更新该资源版本。
   该回调函数返回的参数如下：
   @param namespace 资源的命名空间
   @param res_key 资源标识
   @param res_state_info 资源信息，同{@link M.get_res_state}返回。包含更新信息和当前下载状态
   @param confirm_update_cb 确认是否下载回调，业务方需要对res_update_info是否更新通知该回调，该回调的参数如下：
        @param confirmed true: 确认更新；false: 跳过该更新

3. on_request_res_version SDK请求获取当前资源版本，业务方实现并返回对应资源标识的版本，该接口是异步返回，参数如下：
   @param namespace 资源的命名空间
   @param res_key 资源标识
   @param cb 资源标识版本信息异步回调，回调参数如下：
       @param res_ver 字符串，资源版本，格式为：xxx.xxx.xxx
       @param ext 其它拓展信息

4. on_request_file_list 游戏如果需要根据更新信息自己生成文件下载清单，可以提供该回调。
   如果有该回调则SDK只会使用该回调来生成文件清单，不会做兜底处理。如果没有该回调则SDK自己生成文件清单。
   @param namespace 资源的命名空间
   @param res_key 资源标识
   @file_list_cb 资源清单回调，游戏通过该接口返回清单信息。该回调对应的参数信息如下：
        @param succ 获取文件列表结果，true: 成功；false：失败
        @param ... 可变参数，
            如果succ为true，则该变参为 file_list（文件清单列表）和 list_desc
            > file_list 文件清单列表，是一个数组。里面每个item的字段信息参考：{@link M.FILE_LIST_ITEM_KEY}
            > list_desc 文件清单的附加信息，例如这些清单里面的文件的父目录相对于服务端basePath的相对路径, 可以添加'folder'设置该内容
            如果succ为false, 则该变参为 code 和 msg

5. on_res_state_change_listener 资源下载状态变更通知，返回参数如下：
   @param namespace 资源的命名空间
   @param res_key 资源标识
   @param state 资源下载状态，状态信息参考：{@link M.DOWNLOAD_STATE}
   @param state_obj 详细状态信息，字段参考：{@link M.RES_DOWNLOAD_STATE_KEY}

6. on_res_progress_change_listener 资源下载进度信息，返回参数如下：
   @param namespace 资源的命名空间
   @param res_key 资源标识
   @param progress_info 进度信息，详细见 {@link M.PROGRESS_INFO_KEY}

7. on_res_failed_retry_listener 分发单个资源处理失败回调（对于启动时多个资源更新场景）
   @param namespace 资源的命名空间
   @param res_key 资源标识
   @retry_cb function, 重试回调，无参数
   @param code 错误码
   @param msg 错误信息
   @param ext table, 拓展信息，目前留空
8. on_cache_res_incompatible 检测到本地资源不兼容回调
触发条件：覆盖安装时，包体资源和缓存资源的project_name不同/包体资源的版本大于等于缓存资源的版本
   @param namespace 资源的命名空间
   @param res_key 资源标识
   @param incompatible_data, table, 不兼容的信息, 包含字段如下:
        @param pkg_res_version string, 包体资源版本，例如：1.2.3
        @param res_version string, string, 资源版本，例如：1.2.3
        @param is_version_incompatible, bool, 包体版本和资源版本是否不同
        @param pkg_project_name string, 包体的project_name
        @param cache_res_project_name string, 缓存的资源的project_name
        @param is_project_name_incompatible, bool, 包体的project_name和缓存资源的project_name是否不同
   @param local_res_state_info table，本地的资源信息，同{@link ejoysdk_res_facade.lua get_res_state返回}详细见：https://aliyuque.antfin.com/ejoy-platform/user_guide/dh49th#NG925
   @param process_cb function, 处理结果回调，回调参数如下:
        @param succ, boolean, true:成功， false:失败
        true: 此时无其它参数
        false: 此时第2, 3个参数分为code, msg
9. on_startup_config_changed 获取启动时配置信息回调（namespace 为 qz_config），返回信息如下：
    @param cur_product_code string, 当前平台productcode
    @param is_review bool, 是否提审中，true: 提审中，false: 非提审中
    @param public_startup_config table, 启动时平台product_code对应的启动配置信息，包含内容如下：
      @param product_code, 游戏启动时默认的平台product_code, 例如: p10445, 注意：p统一为小写
      @param config: 上面product_code对应启动配置信息（qz_config namespace对应的配置）
    @param review_startup_config table, 提审环境平台prduct_code对应的启动配置信息，包含内容如下：
        @param product_code, 提审环境平台product_code, 例如: p10445, 注意：p统一为小写
      @param config: 上面product_code对应启动配置信息（qz_config namespace对应的配置）
    @param cb function, 游戏处理完回调，SDK在游戏处理完后继续下面的流程
@param ext_infos, table, 拓展信息，包含以下字段：
    @param {@link M.NAMESPACE_UPDATE_EXT_INFOS.QZ_PRODUCT_CODE}, 轻舟product_code，可以和运营平台的product_code区分开传递
--]]
function M.startup_check_update(current_res_info_arr, opts, listeners, ext_infos)
    local EM = require "ejoysdk_lua.res.startup_res_manager"
    ext_infos = ext_infos or {}
    local params = {
        current_res_info_arr = current_res_info_arr,
        qz_product_code = ext_infos[M.NAMESPACE_UPDATE_EXT_INFOS.QZ_PRODUCT_CODE]
    }
    EM.startup_check_update(params, opts, listeners)
end

